(async () => {
  const src = document.querySelector('.task-board[data-task-id="4"]');
  const dst = document.querySelector('.board-task-list:has(.task-board[data-task-id="1"])');
  if(!src||!dst) return 'missing '+!!src+' '+!!dst;
  const sr = src.getBoundingClientRect(); const dr = dst.getBoundingClientRect();
  const sx = sr.left+sr.width/2, sy = sr.top+sr.height/2;
  const dx = dr.left+dr.width/2, dy = dr.top+Math.min(40,dr.height/2);
  const mk=(t,x,y,el)=>el.dispatchEvent(new MouseEvent(t,{bubbles:true,cancelable:true,clientX:x,clientY:y,button:0,buttons:t==='mouseup'?0:1,view:window}));
  mk('mousedown',sx,sy,src);
  for(let i=1;i<=15;i++){
    const x=sx+(dx-sx)*i/15, y=sy+(dy-sy)*i/15;
    mk('mousemove',x,y,document);
    await new Promise(r=>setTimeout(r,30));
  }
  mk('mousemove',dx,dy,document);
  mk('mouseup',dx,dy,document);
  await new Promise(r=>setTimeout(r,1200));
  return 'seq-done';
})()
